const L = bench_length, sh = seat_height, D = depth, n = Math.round(slats), t = 0.035, g = 0.012;
const w = (D - (n - 1) * g) / n;
const add = (p, s, rot, k) => { const q = addpoint(0, p); setpointattrib(0, 'scale', q, s); setpointattrib(0, 'orient', q, quaternion(radians(rot), [1, 0, 0])); setpointattrib(0, 'tint', q, 0.85 + 0.25 * rand(k, seed)); };
for (let i = 0; i < n; i++) add([0, sh - t / 2, -D / 2 + w / 2 + i * (w + g)], [L, t, w], 0, i);
if (backrest) {
  const a = radians(15);
  for (let i = 0; i < 3; i++) { const h = 0.12 + i * 0.13; add([0, sh + 0.02 + h * Math.cos(a), -D / 2 + 0.01 - h * Math.sin(a)], [L, 0.1, t], -15, 10 + i); }
}

